terms.medium_def:
A woman living at the time of Divided Monarchy, only mentioned at 2Ki.21.1; 
only referred to as Hephzibah (חֶפְצִי־בָהּ); 
wife of Hezekiah; 
mother of Manasseh.

People from Jebus(?) of the Canaanites, first mentioned at Gen.10.16; 
only referred to as Jebusites (יְבוּסִי); 
descended from Canaan along with Sidon, Heth, Amorites, Girgashites, Hivites, Arkites, Sinites, Arvadites, Zemarites and Hamathites. § descendants of the 3rd son of Canaan who lived in or around the site of Jebus, the early name for Jerusalem

terms.lsj_entry:
Σιών 
indecl., 
in NT anarth., but in LXX when used of the city of Jerusalem, ἡ Σ. 
(Heb. צִיּוֹן), 
Zion; 
__1. the mountain: in typical sense, of the Church, Heb.12:22; of heaven, Rev.14:1. 
__2. The city, i.e. Jerusalem; in poetical sense; 
__(a) of the inhabitants: θυγάτηρ Σ, Mat.21:5, Jhn.12:15" (LXX) ; 
__(b) in wider sense, of Israel: Rom.11:26; 
__(with) figuratively: τίθήμι ἐν Σ λίθον, Rom.9:33, 1Pe.2:6" (LXX) .†
(From Abbott-Smith. LSJ has no entry)

terms.medium_def:
A location first mentioned at Jos.10.1; 
referred to as Jerusalem (יְרוּשָׁלִַ֫ם, יְרוּשְׁלֵם), or Jerusalem (Aramiac יְרוּשָׁלִַ֫ם, יְרוּשְׁלֵם), or Ariel (אֲרִיאֵל), or My Delight Is in Her (KJV= Hephzibah) (חֶפְצִי־בָהּ), or Forsaken (NIV= Deserted) (עָזַב), or Desolate (שְׁמָמָה), or Married (KJV, NIV= Beulah) (בָּעַל), or Jebus (יְבוּס), or Jebus or Jebusite (יְבוּסִי), or The Lord/ Is There (יְהֹוָה שָׁם), or The Lord/ Is There (=Alt tag) (יְהֹוָה שָׁמָּה), or City/ of the Lord (יְהֹוָה עִיר), or Salem (שָׁלֵם), or Zion or (Mount )Zion (צִיּוֹן), or Jerusalem (Ἱεροσόλυμα), or Jerusalem (Ἱερουσαλήμ), or Jerusalem (Ἱεροσολυμίτης), or Salem (Σαλήμ), or Zion or (Mount )Zion (KJV= Sion) (Σιών). § the place of which Melchizedek was king
most Jewish commentators affirm that it is the same as Jerusalem

A location in Judah Tribe near Tekoa only mentioned at 1Ch.4.12; 
referred to as Ir-nahash (עִיר נָחָשׁ), or Ir-nahash (NIV= Ir Nahash) (=Alt tag) (עִיר נָחָשׁ); 
founded by Tehinnah - perhaps a person, the son of Tehinnah. §#A man of the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.4.12; 
son of: Tehinnah (H8468)

A location first mentioned at Jos.12.24; 
only referred to as Tirzah (תִּרְצָה). § one of the kingdoms on the west of the Jordan conquered by Joshua and the Israelites
a Canaanite city, later capital of the northern kingdom of Israel

A woman from the tribe of Manasseh living at the time of Egypt and Wilderness, first mentioned at Num.26.33; 
only referred to as Tirzah (תִּרְצָה); 
daughter of Zelophehad; 
a sister of Mahlah, Noah, Hoglah and Milcah.

A woman living before Israel's Monarchy, first mentioned at Rut.1.2; 
referred to as Naomi (נׇעֳמִי), or Mara (מָרָא); 
wife of Elimelech; 
mother of Mahlon and Chilion. § wife of Elimelech, mother of Mahlon and Chilion, and mother-in-law of Ruth and Orpah

People from Naamath(?), first mentioned at Job.2.11; 
only referred to as Naamathites (נַעֲמָתִי). § Naamathite, of Naamah "pleasantness"
an inhabitant of Naamah ; describes Zophar the friend of Job

A woman of the Ammonites living at the time of United Monarchy, first mentioned at 1Ki.14.21; 
only referred to as Naamah (נַעֲמָה); 
wife of Solomon; 
mother of Rehoboam.

A man from the tribe of Benjamin living at the time of Egypt and Wilderness, first mentioned at Num.26.40; 
referred to as Naaman (נַעֲמָן), or Naamite (נַעֲמִי); 
son of Bela; 
a brother of Ard, Ezbon, Uzzi, Uzziel, Jerimoth, Iri, Addar, Gera, Abihud, Abishua and Ahoah.

A man from the tribe of Judah living before Israel's Monarchy, only mentioned at 1Ch.4.15; 
only referred to as Naam (נָ֑עַם); 
son of Caleb; 
a brother of Achsah, Iru and Elah. § one of the sons of Caleb and grandson of Jephunneh

A woman living at the time before the Flood, only mentioned at Gen.4.22; 
only referred to as Naamah (נַעֲמָה); 
daughter of Lamech and Zillah; 
a sister of Jabal, Jubal, Tubal-cain; 
According to some traditions, wife of Noah and mother of Shem, Ham and Japheth. § a town in the lowlands of Judah in Philistia

A man from the tribe of Benjamin living at the time of Egypt and Wilderness, first mentioned at Num.26.40; 
referred to as Naaman (נַעֲמָן), or Naamite (נַעֲמִי); 
son of Bela; 
a brother of Ard, Ezbon, Uzzi, Uzziel, Jerimoth, Iri, Addar, Gera, Abihud, Abishua and Ahoah. § Naamites, of Naamah "loveliness"
the descendants of Naaman, the grandson of Benjamin

A man from the tribe of Benjamin living at the time of Egypt and Wilderness, first mentioned at Gen.46.21; 
referred to as Naaman (נַעֲמָן), or Nohah (נוֹחָה); 
son of Benjamin; 
a brother of Bela, Becher, Ashbel, Gera, Ahiram, Rosh, Muppim, Huppim, Ard, Ahiram and Jediael.

A man from the tribe of Benjamin living before Israel's Monarchy, only mentioned at 1Ch.8.7; 
only referred to as Naaman (נַעֲמָן); 
son of Ehud; 
a brother of Ahijah, Gera, Uzza and Ahihud.

A man from the tribe of Judah living at the time of Egypt and Wilderness, first mentioned at Gen.46.12; 
referred to as Hamul (חָמוּל), or Hamulite (חָמוּלִי); 
son of Perez; 
a brother of Hezron. § the younger son of Pharez, Judah's son by Tamar

A man from the tribe of Judah living at the time of Egypt and Wilderness, first mentioned at Gen.46.12; 
referred to as Hamul (חָמוּל), or Hamulite (חָמוּלִי); 
son of Perez; 
a brother of Hezron. § descendants of Hamul, grandson of Judah by Tamar

A man living at the time of Divided Monarchy, only mentioned at 1Ch.11.42; 
only referred to as Adina (עֲדִינָא); 
a son of Shiza. § a chief of the Reubenites, and a captain of David

A man living at the time of Divided Monarchy, only mentioned at 2Ch.29.12; 
only referred to as Eden (עֵ֫דֶן); 
a son of Joah. § a Gershonite Levite, son of Joah in the days of king Hezekiah of Judah

A man living at the time of the Patriarchs, first mentioned at Gen.36.26; 
referred to as Hemdan (חֶמְדָּן), or Hemdan (KJV= Amram) (חַמְרָן); 
son of Dishon; 
a brother of Eshban, Ithran and Cheran. § the eldest son of Dishon, son of Anah the Horite

A man from the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.2.47; 
only referred to as Shaaph (שַׁ֫עַף); 
son of Caleb and Jahdai; 
a brother of Regem, Jotham, Geshan, Pelet and Ephah, Hur(?), Jesher(?), Shobab(?), Ardon(?), Mesha(?), Haran(?), Moza(?), Gazez(?), Sheber(?), Tirhanah(?), Shaaph(?), Sheva(?) and Achsah(?).

A man from the tribe of Judah living at the time of Egypt and Wilderness, only mentioned at 1Ch.2.49; 
only referred to as Shaaph (שַׁ֫עַף); 
son of Caleb and Maacah; 
a brother of Sheber, Tirhanah and Sheva; 
half-brother of: Hur, Jesher, Shobab, Ardon, Mesha, Haran, Moza, Gazez and Achsah; 
father of Madmannah or founder of Madmannah.

Nehemiah's adversary of the Ammonites living at the time of Exile and Return, first mentioned at Neh.2.10; 
only referred to as Tobiah (טוֹבִיָּ֫הוּ); 
husband of daughter_of_Shecaniah; 
father of Jehohanan.

A prophet living at the time of United Monarchy, first mentioned at 2Sa.7.2; 
only referred to as Nathan (נָתָן); 
father of Azariah, Zabud.

A man living at the time of Divided Monarchy, first mentioned at 2Ki.25.23; 
only referred to as Nethaniah (נְתַנְיָ֫הוּ); 
a son of Elishama; 
father of Ishmael.

A Singer from the tribe of Levi living at the time of United Monarchy, first mentioned at 1Ch.15.18; 
only referred to as Mattithiah (מַתִּתְיָ֫הוּ); 
son of Jeduthun; 
a brother of Obed-edom, Gedaliah, Zeri, Jeshaiah, Hashabiah.

David's son from the tribe of Judah living at the time of United Monarchy, first mentioned at 2Sa.5.14; 
referred to as Nathan (נָתָן), or Nathan (Ναθάν); 
son of David and Bathsheba; 
a brother of Shammua, Shobab and Solomon; 
half-brother of: Amnon, Chileab, Absalom, Adonijah, Shephatiah, Ithream, Ibhar, Elishua, Nepheg, Japhia, Elishama, Eliada, Eliphelet, Tamar, Elpelet, Nogah and Jerimoth; 
father of Mattatha.

A man living at the time of Egypt and Wilderness, first mentioned at Num.1.8; 
only referred to as Nethanel (נְתַנְאֵל); 
a son of Zuar.

A man from the tribe of Levi living at the time of Exile and Return, first mentioned at 1Ch.9.15; 
only referred to as Mattaniah (מַתַּנְיָ֫הוּ); 
a son of Mica.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.25.4; 
only referred to as Mattaniah (מַתַּנְיָ֫הוּ); 
son of Heman; 
a brother of Bukkiah, Uzziel, Shebuel, Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, Romamti-ezer, Joshbekashah, Mallothi, Hothir, Mahazioth.

A man living at the time of Exile and Return, first mentioned at Neh.11.22; 
only referred to as Mattaniah (מַתַּנְיָ֫הוּ); 
a son of Mica; 
father of Hashabiah, Shemaiah.

A man living at the time of United Monarchy, first mentioned at 2Sa.23.36; 
only referred to as Nathan (נָתָן); 
a brother of Joel; 
father of Igal.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.25.2; 
only referred to as Nethaniah (נְתַנְיָ֫הוּ); 
son of Asaph; 
a brother of Zaccur, Joseph and Asharelah.

A man living at the time of Divided Monarchy, only mentioned at Jer.38.1; 
only referred to as Mattan (מַתָּן); 
father of Shephatiah.

A man living at the time of Divided Monarchy, only mentioned at 2Ch.20.14; 
only referred to as Mattaniah (מַתַּנְיָ֫הוּ); 
father of Jeiel.

A man living at the time of Exile and Return, only mentioned at Neh.13.13; 
only referred to as Mattaniah (מַתַּנְיָ֫הוּ); 
father of Zaccur.

A king of Judah living at the time of Divided Monarchy, first mentioned at 2Ki.24.17; 
referred to as Zedekiah (צִדְקִיָּ֫הוּ), or Mattaniah (מַתַּנְיָ֫הוּ); 
son of Josiah and Hamutal; 
a brother of Jehoahaz; 
half-brother of: Jehoiakim and Shallum.

A man from the tribe of Levi living at the time of Exile and Return, only mentioned at 1Ch.9.31; 
only referred to as Mattithiah (מַתִּתְיָ֫הוּ); 
a son of Shallum.

A man from the tribe of Judah living at the time of Divided Monarchy, first mentioned at 1Ch.2.36; 
only referred to as Nathan (נָתָן); 
a son of Attai; 
father of Zabad.

David's brother from the tribe of Judah living at the time of United Monarchy, only mentioned at 1Ch.2.14; 
only referred to as Nethanel (נְתַנְאֵל); 
son of Jesse; 
a brother of David, Eliab, Abinadab, Shimeah, Raddai, Ozem, Zeruiah, Abigail(?) and Elihu.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.24.6; 
only referred to as Nethanel (נְתַנְאֵל); 
father of Shemaiah.

A man from the tribe of Levi living at the time of United Monarchy, only mentioned at 1Ch.26.4; 
only referred to as Nethanel (נְתַנְאֵל); 
son of Obed-edom; 
a brother of Shemaiah, Jehozabad, Joah, Sachar, Ammiel, Issachar and Peullethai.

A man living at the time of Exile and Return, only mentioned at Neh.12.36; 
only referred to as Nethanel (נְתַנְאֵל); 
son of Jonathan; 
a brother of Zechariah, Shemaiah, Azarel, Milalai, Gilalai, Maai, Judah and Hanani.

A man living at the time of Divided Monarchy, only mentioned at Jer.36.14; 
only referred to as Nethaniah (נְתַנְיָ֫הוּ); 
a son of Shelemiah; 
father of Jehudi.
